    "REGISTERED",
    "OPEN",
    "COMMIT",
    "REVEAL",
    "SETTLED_CREATOR",
    "SETTLED_CHALLENGER",
    "ABORTED",
    "EXPIRED_UNCHALLENGED",
    "EXPIRED_UNFUNDED"
   ]
  },
  "posting_deadline": {
   "type": "integer",
   "format": "int64",
   "minimum": 0
  },
  "required_votes": {
   "type": "integer",
   "minimum": 0
  },
  "reveal_deadline": {
   "type": "integer",
